export function Chart({analysis}:{analysis:any}){
 const [metric,setMetric]=useState('revenue');
 const options=[{key:'revenue',title:'الإيرادات'},{key:'netProfit',title:'صافي الربح'},{key:'operatingProfit',title:'الربح التشغيلي'},{key:'grossMargin',title:'هامش إجمالي الربح'},{key:'operatingMargin',title:'هامش التشغيل'},{key:'netMargin',title:'هامش صافي الربح'}];
 const current=options.find(item=>item.key===metric)||options[0];const ratio=metric.endsWith('Margin');
 const qs=Array.isArray(analysis?.quarters)?analysis.quarters:[];const vals=qs.map((q:any)=>q[metric]).filter((value:any)=>typeof value==='number'&&Number.isFinite(value));
 const rawMin=Math.min(0,...vals),rawMax=Math.max(0,...vals);const span=rawMax-rawMin||1;const low=rawMin<0?rawMin-span*.16:0,high=rawMax>0?rawMax+span*.16:rawMin<0?0:1;const range=high-low||1;
 const y=(value:number)=>28+(high-value)/range*181;const zeroY=y(0);const points=qs.map((q:any,i:number)=>({q,x:82+i*(568/Math.max(qs.length-1,1)),value:typeof q[metric]==='number'&&Number.isFinite(q[metric])?q[metric]:null}));
 const segments:string[][]=[];let line:string[]=[];for(const point of points){if(point.value===null){if(line.length)segments.push(line);line=[];}else line.push(`${point.x},${y(point.value)}`)}if(line.length)segments.push(line);
 const ticks=[low,(low+high)/2,high,0].filter((value,index,array)=>array.findIndex(item=>Math.abs(item-value)<range*.04)===index).sort((a,b)=>a-b);
 return <div className="financial-chart"><div className="card-heading financial-chart-heading"><div><h3>{current.title}</h3><p>{ratio?'نسبة مئوية':'مليون ريال سعودي'} · أرقام كل ربع على حدة</p></div><label><span className="sr-only">مؤشر الرسم المالي</span><select aria-label="مؤشر الرسم المالي" value={metric} onChange={event=>setMetric(event.target.value)}>{options.map(item=><option key={item.key} value={item.key}>{item.title}</option>)}</select><ChevronDown size={14}/></label></div>{!vals.length?<div className="empty financial-chart-empty"><ChartNoAxesCombined size={26}/><p>لا توجد قيم موثقة لهذا المؤشر في الأرباع المسجلة.</p></div>:<div className="chart-wrap"><svg viewBox="0 0 720 274" role="img" aria-label={`اتجاه ${current.title}، ${ratio?'بالنسبة المئوية':'بمليون ريال'}. القيم المفقودة لا تُرسم كأصفار.`}><title>{`${current.title} حسب الربع`}</title><desc>يتضمن الرسم خط الصفر، وتظهر القيم السالبة أسفله. ينقطع الخط عند غياب قيمة الربع.</desc>{ticks.map((value,index)=><g key={index}><line x1="67" x2="678" y1={y(value)} y2={y(value)} stroke={value===0?'#ae9bbc':'#eae4f0'} strokeWidth={value===0?1.5:1} strokeDasharray={value===0?undefined:'4 5'}/><text x="56" y={y(value)+4} textAnchor="end" fill="#8d789b" fontSize="11">{num(value)}{ratio?'٪':''}</text></g>)}{segments.filter(segment=>segment.length>1).map((segment,index)=><polyline key={index} points={segment.join(' ')} stroke="#8055ad" strokeWidth="3" fill="none" strokeLinejoin="round" strokeLinecap="round"/>)}{points.map((point:any,index:number)=><g key={point.q.period||index}>{point.value!==null?<><circle cx={point.x} cy={y(point.value)} r="5" fill={point.value<0?'#b65775':'#8055ad'} stroke="white" strokeWidth="2.5"/><text x={point.x} y={y(point.value)+(point.value<0?21:-14)} textAnchor="middle" fill={point.value<0?'#ad506b':'#75538d'} fontSize="12" fontWeight="600">{num(point.value)}{ratio?'٪':''}</text></>:<text x={point.x} y="225" textAnchor="middle" fill="#b4a0c1" fontSize="10">غير متاح</text>}<text x={point.x} y="252" textAnchor="middle" fill="#957fa4" fontSize="11">{quarter(point.q.period)}</text></g>)}</svg></div>}<details className="financial-chart-values"><summary>عرض أرقام الرسم<ChevronDown size={13}/></summary><div>{points.map((point:any,index:number)=><span key={point.q.period||index}>{quarter(point.q.period)}<strong>{point.value===null?'—':`${num(point.value)}${ratio?'٪':''}`}</strong></span>)}</div></details></div>
}

