 function startResearch(companyId:string){if(!researchCompanies.some(company=>company.id===companyId))return;setNav('agent');setMobile(false);setLaunchCompanyId(companyId);setLaunchQuery(researchCompanies.find(company=>company.id===companyId)?.name||'');setLaunchOpen(false);requestAnimationFrame(()=>{window.dispatchEvent(new CustomEvent('drast:start-research',{detail:{companyId}}));document.querySelector('.research-desk')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})})}
 function openResearch(section:'today'|'reports'){setNav('agent');setMobile(false);requestAnimationFrame(()=>{window.dispatchEvent(new CustomEvent('drast:open-research',{detail:section}));document.querySelector('.research-desk')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})})}
 useEffect(()=>{let anchor=window.scrollY,frame=0;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');const update=()=>{const current=window.scrollY;if(current<90||reduced.matches||mobile){setHeaderHidden(false);anchor=current}else if(Math.abs(current-anchor)>8){setHeaderHidden(current>anchor);anchor=current}frame=0};const onScroll=()=>{if(!frame)frame=requestAnimationFrame(update)};window.addEventListener('scroll',onScroll,{passive:true});update();return()=>{window.removeEventListener('scroll',onScroll);cancelAnimationFrame(frame)}},[mobile]);
 const study=studies.find(s=>s.id===activeId)||studies[0];const analysis=useMemo(()=>analyzeStudy(study||{}),[study]);const latest=analysis.quarters.find((q:any)=>q.period===analysis.summary.latestPeriod);const sectors=[...new Set(studies.map(s=>s.sector).filter(Boolean))];const visible=studies.filter(s=>(sector==='all'||s.sector===sector)&&`${s.company} ${s.ticker} ${s.sector}`.toLocaleLowerCase('ar-SA').includes(query.trim().toLocaleLowerCase('ar-SA')));
 const navItems=[{id:'agent',icon:Sparkles,title:'مكتب البحث'},{id:'directory',icon:BookOpen,title:'الفهرس'},{id:'studies',icon:LayoutDashboard,title:'دراسات الشركات'},{id:'compare',icon:Layers3,title:'مقارنة المؤشرات'},{id:'sources',icon:FolderOpen,title:'مكتبة المصادر'}];
